/**
 * Read-only. For every checked-in migration, extract the tables it creates and
 * the columns it adds, then check whether the dev database already has them.
 * Baselining is only correct if the effects are already present.
 */
const fs = require("fs");
const path = require("path");
const { Client } = require("pg");

const DIR = "/home/runner/workspace/migrations";
const files = fs
  .readdirSync(DIR)
  .filter((f) => f.endsWith(".sql"))
  .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));

function unquote(s) {
  return s.replace(/^"|"$/g, "").replace(/^public\./, "").replace(/^"public"\./, "");
}

function extract(sql) {
  const tables = new Set();
  const columns = new Set();

  const tableRe = /CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?("?[\w.]+"?)/gi;
  let m;
  while ((m = tableRe.exec(sql))) tables.add(unquote(m[1]));

  // ALTER TABLE t ADD COLUMN [IF NOT EXISTS] c ... , ADD COLUMN c2 ...
  const alterRe = /ALTER\s+TABLE\s+(?:IF\s+EXISTS\s+)?("?[\w.]+"?)([\s\S]*?);/gi;
  while ((m = alterRe.exec(sql))) {
    const table = unquote(m[1]);
    const body = m[2];
    const colRe = /ADD\s+COLUMN\s+(?:IF\s+NOT\s+EXISTS\s+)?("?\w+"?)/gi;
    let c;
    while ((c = colRe.exec(body))) columns.add(`${table}.${unquote(c[1])}`);
  }
  return { tables: [...tables], columns: [...columns] };
}

(async () => {
  const client = new Client({ connectionString: process.env.DATABASE_URL });
  await client.connect();

  const dbTables = new Set(
    (
      await client.query(
        "select table_name from information_schema.tables where table_schema='public'",
      )
    ).rows.map((r) => r.table_name),
  );
  const dbColumns = new Set(
    (
      await client.query(
        "select table_name || '.' || column_name as ref from information_schema.columns where table_schema='public'",
      )
    ).rows.map((r) => r.ref),
  );

  let anyMissing = false;
  for (const file of files) {
    const sql = fs.readFileSync(path.join(DIR, file), "utf8");
    const { tables, columns } = extract(sql);
    const missingTables = tables.filter((t) => !dbTables.has(t));
    const missingColumns = columns
      .filter((c) => dbTables.has(c.split(".")[0]))
      .filter((c) => !dbColumns.has(c));

    const status =
      missingTables.length === 0 && missingColumns.length === 0 ? "OK  " : "GAP ";
    if (status === "GAP ") anyMissing = true;
    console.log(
      `${status} ${file.padEnd(46)} tables:${tables.length - missingTables.length}/${tables.length} cols:${columns.length - missingColumns.length}/${columns.length}`,
    );
    if (missingTables.length) console.log(`       missing tables : ${missingTables.join(", ")}`);
    if (missingColumns.length) console.log(`       missing columns: ${missingColumns.join(", ")}`);
  }

  console.log("");
  console.log(anyMissing ? "RESULT: gaps found" : "RESULT: every declared table/column is present");
  await client.end();
})().catch((e) => {
  console.error(e);
  process.exit(1);
});

