/**
 * Read-only live verification of the migration runner against the dev DB.
 * Deleted after use.
 */
import fs from "fs";
import os from "os";
import path from "path";

import {
  checksumAll,
  formatPendingReport,
  listMigrationFiles,
  planMigrations,
  readMigrationLedgerIfPresent,
  reportPendingMigrations,
  type MigrationClient,
} from "../server/migrate";

async function main() {
  console.log("─── 1. startup check against the live dev DB ───");
  await reportPendingMigrations();

  const pg = await import("pg");
  const client = new pg.default.Client({
    connectionString: process.env.DATABASE_URL,
  });
  await client.connect();
  const ledger = (await readMigrationLedgerIfPresent(client as unknown as MigrationClient))!;

  console.log("");
  console.log("─── 2. drift detection against the REAL ledger ───");
  // Copy the real migrations into a temp dir and change one byte of one file.
  // Nothing is written to the database or to the repo.
  const realDir = listMigrationFiles();
  const srcDir = path.resolve(process.cwd(), "migrations");
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "drift-"));
  for (const f of realDir) fs.copyFileSync(path.join(srcDir, f), path.join(tmp, f));

  const victim = "0011_payment_links_and_board_numbers.sql";
  fs.appendFileSync(path.join(tmp, victim), "\n-- someone edited an applied migration\n");

  const plan = planMigrations(realDir, checksumAll(tmp, realDir), ledger);
  console.log(
    `plan: applied=${plan.applied.length} pending=${plan.pending.length} ` +
      `drifted=${plan.drifted.length} orphaned=${plan.orphaned.length}`,
  );
  for (const line of formatPendingReport(plan)) console.log(line);

  console.log("");
  console.log("─── 3. pending detection: a brand-new migration file appears ───");
  const tmp2 = fs.mkdtempSync(path.join(os.tmpdir(), "pending-"));
  for (const f of realDir) fs.copyFileSync(path.join(srcDir, f), path.join(tmp2, f));
  fs.writeFileSync(
    path.join(tmp2, "0014_hypothetical_next.sql"),
    "ALTER TABLE merchants ADD COLUMN IF NOT EXISTS example text;\n",
  );
  await reportPendingMigrations({ dir: tmp2, log: (m) => console.log(m) });

  fs.rmSync(tmp, { recursive: true, force: true });
  fs.rmSync(tmp2, { recursive: true, force: true });
  await client.end();
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

