async function snapshot(url) {
  const c = new Client({ connectionString: url });
  await c.connect();
  const cols = await c.query(
    `select table_name || '.' || column_name as ref
       from information_schema.columns
      where table_schema='public' order by 1`,
  );
  const tables = await c.query(
    `select table_name from information_schema.tables
      where table_schema='public' and table_type='BASE TABLE' order by 1`,
  );
  await c.end();
  return {
    tables: new Set(tables.rows.map((r) => r.table_name)),
    columns: new Set(cols.rows.map((r) => r.ref)),
  };
}

(async () => {
  const scratchUrl = require("fs")
    .readFileSync("/home/runner/workspace/.tmp-repro/scratch-url.txt", "utf8")
    .trim();
  const dev = await snapshot(process.env.DATABASE_URL);
  const fresh = await snapshot(scratchUrl);

  const diff = (a, b) => [...a].filter((x) => !b.has(x));

  console.log(`dev tables: ${dev.tables.size}   migration-built tables: ${fresh.tables.size}`);
