  // before the first INSERT.
  const { client, calls, texts } = createFakeClient({
    onQuery(text) {
      if (text.startsWith("SELECT filename")) {
        throw Object.assign(new Error("relation does not exist"), { code: "42P01" });
      }
      return undefined;
    },
  });

